'use strict';
window.ValuationExport=(()=>{
 function sheet(w,name,rows){const ws=XLSX.utils.json_to_sheet(rows);const heads=[...new Set(rows.flatMap(r=>Object.keys(r)))];ws['!cols']=heads.map(h=>({wch:Math.min(42,Math.max(18,h.length+2))}));XLSX.utils.book_append_sheet(w,ws,name);return ws;}
 function formula(ws,cell,f,v){ws[cell]={t:typeof v==='string'?'s':'n',f,v};if(typeof v==='number')ws[cell].z='0.00000000';}
 function book(){const w=XLSX.utils.book_new();w.Workbook={CalcPr:{fullCalcOnLoad:true}};return w;}
 function info(w,r){sheet(w,'Run info',[...Object.entries(r.runInfo).map(([Setting,Value])=>({Setting,Value})),{Setting:'Scope',Value:'Internal arithmetic reconciliation, not independent market-price validation. EUR lender/asset cash flows.'},{Setting:'Editing',Value:'Recalculate in Excel. This workbook audits the captured run; edited terms do not regenerate schedules or curve interpolation.'},{Setting:'Tolerance',Value:'EUR 0.01. Future reference rates use full index tenor; known fixing excludes spread.'}]);}
 function all(r){const w=book();for(const [name,key]of [['Summary','summary'],['Cash flows','cashflows'],['Errors','errors'],['Inputs','inputs'],['Curves','curves']])sheet(w,name,r[key]);info(w,r);return w;}
 function validation(r,id){const match=x=>String(x['Source row'])===String(id),summary=r.summary.find(match);if(!summary)throw Error('Select a product.');const w=book(),flows=r.cashflows.filter(match);sheet(w,'Summary',[summary]);sheet(w,'Inputs',r.sourceInputs.filter(x=>String(x._row)===String(id)));const used=new Set([summary['Discount curve'],summary['Projection curve']]);sheet(w,'Curve inputs',r.curves.filter(x=>used.has(x['Curve ID'])));if(summary.Status!=='OK'){sheet(w,'Errors',r.errors.filter(match));info(w,r);return w;}
 const seen=new Map(),resets=[];for(const f of flows)if(f['Reset date']&&!seen.has(f['Reset date'])){seen.set(f['Reset date'],resets.length+2);resets.push({'Reset date':f['Reset date'],'Index end':f['Index end date'],'Source':f['Rate source'],'Start DF':f['Projection start DF'],'End DF':f['Projection end DF'],'Index accrual':f['Index accrual fraction'],'Engine reference %':f['Reference rate %'],'Recalculated reference %':f['Reference rate %'],'Spread %':f['Spread %'],'Recalculated coupon %':f['Coupon rate %'],'Reference difference':0});}
 const rs=sheet(w,'Reset audit',resets);resets.forEach((r,i)=>{const n=i+2;const reference=r['Start DF']!==''?(r['Start DF']/r['End DF']-1)/r['Index accrual']*100:r['Engine reference %'];r['Recalculated reference %']=reference;r['Recalculated coupon %']=reference+r['Spread %'];formula(rs,'H'+n,r['Start DF']!==''?`(D${n}/E${n}-1)/F${n}*100`:`G${n}`,reference);formula(rs,'J'+n,`H${n}+I${n}`,r['Recalculated coupon %']);formula(rs,'K'+n,`H${n}-G${n}`,reference-r['Engine reference %']);});
 const cf=flows.map(f=>({'Payment date':f['Payment date'],'Period start':f['Period start'],'Opening balance':f['Opening balance']??summary.Notional,'Coupon %':f['Coupon rate %'],'Accrual fraction':f['Accrual fraction'],'Engine interest':f.Interest,'Recalculated interest':f.Interest,'Principal':f.Principal,'Closing balance':f['Closing balance']??(f.Principal?0:summary.Notional),'Recalculated payment':f['Total payment'],'Discount factor':f['Discount factor'],'Engine PV':f['Present value'],'Recalculated PV':f['Present value'],'PV difference':0,'Interest difference':0,'Accrued contribution':f['Accrued contribution'],'Balance difference':0,'Base payment DF':f['Base payment DF'],'Settlement DF':f['Settlement DF'],'Discount spread bps':f['Discount spread bps'],'Discount time':f['Discount time']}));const cs=sheet(w,'Cash flow audit',cf);
 cf.forEach((r,i)=>{const n=i+2,f=flows[i];const coupon=f['Reset date']?resets[seen.get(f['Reset date'])-2]['Recalculated coupon %']:r['Coupon %'];const interest=r['Opening balance']*coupon/100*r['Accrual fraction'];const df=f['Base payment DF']/f['Settlement DF']*Math.exp(-f['Discount spread bps']/10000*f['Discount time']);r['Recalculated interest']=interest;r['Recalculated payment']=interest+r.Principal;r['Recalculated PV']=r['Recalculated payment']*df;r['Interest difference']=interest-r['Engine interest'];r['PV difference']=r['Recalculated PV']-r['Engine PV'];r['Balance difference']=r['Opening balance']-r.Principal-r['Closing balance'];formula(cs,'K'+n,`R${n}/S${n}*EXP(-T${n}/10000*U${n})`,df);if(f['Reset date'])formula(cs,'D'+n,`'Reset audit'!J${seen.get(f['Reset date'])}`,coupon);formula(cs,'G'+n,`C${n}*D${n}/100*E${n}`,interest);formula(cs,'J'+n,`G${n}+H${n}`,r['Recalculated payment']);formula(cs,'M'+n,`J${n}*K${n}`,r['Recalculated PV']);formula(cs,'N'+n,`M${n}-L${n}`,r['PV difference']);formula(cs,'O'+n,`G${n}-F${n}`,r['Interest difference']);formula(cs,'Q'+n,`C${n}-H${n}-I${n}`,r['Balance difference']);});
 const last=cf.length+1,range=k=>`'Cash flow audit'!${k}2:${k}${last}`,opening=summary['Outstanding principal']??summary.Notional;
 const checks=[['Dirty PV',summary['Dirty PV'],`SUM(${range('M')})`],['Accrued interest',summary['Accrued interest'],`SUM(${range('P')})`],['Clean PV',summary['Clean PV'],'C2-C3'],['Principal repayment',opening,`SUM(${range('H')})`],['Interest calculation',0,`SUMPRODUCT(ABS(${range('O')}))`],['PV calculation',0,`SUMPRODUCT(ABS(${range('N')}))`],['Balance reconciliation',0,`SUMPRODUCT(ABS(${range('Q')}))`]];
 if(cf.length>1)checks.push(['Balance continuity',0,`SUMPRODUCT(ABS('Cash flow audit'!C3:C${last}-'Cash flow audit'!I2:I${last-1}))`]);
 const sum=(key,abs=false)=>cf.reduce((a,r)=>a+(abs?Math.abs(r[key]):r[key]),0);const actual=[sum('Recalculated PV'),sum('Accrued contribution'),sum('Recalculated PV')-sum('Accrued contribution'),sum('Principal'),sum('Interest difference',true),sum('PV difference',true),sum('Balance difference',true),cf.slice(1).reduce((a,r,i)=>a+Math.abs(r['Opening balance']-cf[i]['Closing balance']),0)];
 const ch=sheet(w,'Checks',checks.map(([Check,Expected])=>({Check,Expected,Recalculated:Expected,Difference:0,Result:'PASS'})));checks.forEach(([name,value,f],i)=>{const n=i+2;formula(ch,'C'+n,f,actual[i]);formula(ch,'D'+n,`C${n}-B${n}`,actual[i]-value);formula(ch,'E'+n,`IF(ABS(D${n})<=0.01,"PASS","FAIL")`,Math.abs(actual[i]-value)<=.01?'PASS':'FAIL');});info(w,r);return w;}
 return {all,validation};
})();
